            globalLines.forEach(line => {
                const parts = line.split(':'); if (parts.length < 2) return;
                const key = parts[0].trim(); const value = parts.slice(1).join(':').trim();
                if (key === '时间') data.date_string = value;
                if (key === '地点') data.location = value;
                if (key === '当前任务') data.global_task = value;
            });
            sections.forEach(charBlock => {
                if (charBlock.trim() === '') return;
                const charData = {};
                charBlock.trim().split('\\n').forEach(line => {
                    const cleanLine = line.trim();
                    if (cleanLine.startsWith('#') || cleanLine === '') return;
                    const parts = cleanLine.split(':'); if (parts.length < 2) return;
