                        <div class="witch-stat-bar-label"><span>好感度</span><span>${char.好感度}/100</span></div>
                        <div class="witch-progress-bar-bg"><div class="witch-progress-bar bar-affinity" style="width: ${char.好感度}%;"></div></div>
