                <div class="witch-top-section">
                    <div class="witch-avatar-section">
                        <div class="witch-avatar-frame">${avatarHtml}</div>
                        <div class="witch-char-name">${char.姓名 || 'Unknown'}</div>
                        <div class="witch-char-title">${char.称号 || ''}</div>
                    </div>
                    <div class="witch-stat-bars">${statsBarHtml}</div>
                </div>`;

            const grid = document.createElement('div');
            grid.className = 'witch-info-grid';

            Object.keys(char).forEach(key => {
                if (!RESERVED_KEYS.includes(key)) {
                    grid.appendChild(createInfoItem(key, char[key]));
                }
            });
            if (char.内心想法) grid.appendChild(createInfoItem('内心想法', char.内心想法));

            view.appendChild(grid);
            return view;
        }

        function renderUI(data) {
            if (container.querySelector('.witch-header-title')) {
                container.querySelector('.witch-header-title').innerHTML = `STATUS - ${data.date_string || 'UNKNOWN'}`;
            }

            if(data.global_task) {
                ui.globalTask.innerHTML = createInfoItem('当前任务', data.global_task).innerHTML;
                ui.globalTask.style.borderColor = '#f59e0b';
                ui.globalTask.style.display = 'flex';
            } else {
                ui.globalTask.style.display = 'none';
            }


            data.characters.sort((a, b) => {
                if (a.姓名 === '贝优妮塔') return -1;
                if (b.姓名 === '贝优妮塔') return 1;
                return 0;
            });

            ui.tabs.innerHTML = '';
            ui.wrapper.innerHTML = '';
            if (!data.characters || data.characters.length === 0) {
                 ui.placeholder.style.display = 'block';
                 ui.wrapper.style.display = 'none';
                 return;
            }
            ui.placeholder.style.display = 'none';
            ui.wrapper.style.display = 'block';

            data.characters.forEach((char, index) => {
                const tab = document.createElement('div');
                tab.className = 'witch-char-tab';
                tab.textContent = char.姓名;
                tab.dataset.charIndex = index;
                ui.tabs.appendChild(tab);
                const detailView = createDetailView(char);
                ui.wrapper.appendChild(detailView);
                tab.addEventListener('click', () => {
                    document.querySelectorAll('.witch-char-tab').forEach(t => t.classList.remove('active'));
                    tab.classList.add('active');
                    document.querySelectorAll('.character-detail-view').forEach(v => v.classList.remove('active'));
                    detailView.classList.add('active');
                });
            });

            if (ui.tabs.firstChild) {
                ui.tabs.firstChild.click();
            }
        }

        toggleBtn.addEventListener('click', () => {
            container.classList.toggle('collapsed');
            const isCollapsed = container.classList.contains('collapsed');
            toggleBtn.innerHTML = isCollapsed ? '&#9660;' : '&#9650;';
        });

        const rawData = dataContainer.textContent.trim().replace(/\[魔女启\]|\[魔女关\]/g, '').replace(/\n/g, '\\n');
        if (rawData) {
            const parsedData = parseData(rawData);
            renderUI(parsedData);
        } else {
            console.error("No data in container.");
            ui.placeholder.style.display = 'block';
            ui.wrapper.style.display = 'none';
        }
    });
    </script>
</body>
