        .witch-progress-bar { height: 100%; border-radius: 8px; transition: width 0.5s ease-in-out; box-shadow: inset 0 0 5px rgba(0,0,0,0.3); }
        .bar-affinity { background: linear-gradient(90deg, #f472b6, #c026d3); }
        .witch-info-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; }
        .witch-info-item {
            background-color: rgba(26, 17, 42, 0.5); padding: 12px 15px; border-radius: 8px;
            border-left: 4px solid #8b5cf6; transition: all 0.3s ease; backdrop-filter: blur(2px);
            display: flex; align-items: center; gap: 12px;
        }
        .witch-info-item:hover { transform: scale(1.03); background-color: rgba(26, 17, 42, 0.8); }
        .witch-info-icon { width: 24px; min-width: 24px; height: 24px; fill: #d8b4fe; opacity: 0.8; }
        .witch-info-content { display: flex; flex-direction: column; }
        .witch-info-label { font-weight: 700; color: #a78bfa; font-size: 0.85em; margin-bottom: 3px; text-transform: uppercase; }
        .witch-info-value { color: #f3e8ff; font-size: 1.05em; font-weight: 400; word-wrap: break-word; }
        .border-thoughts { grid-column: 1 / -1; }
        .no-char-selected { text-align: center; font-size: 1.8em; color: #a78bfa; padding: 150px 20px; width:100%; text-shadow: 0 0 10px rgba(167, 139, 250, 0.7);}
    </style>
</head>
<body>
    <div class="witch-status-data-container">$1</div>
    <div class="witch-status-container witch-collapsible-content">
        <div class="witch-header-info">
            <span class="witch-header-title">Bayonetta</span>
            <button class="witch-header-toggle-btn">&#9650;</button>
        </div>
        <div class="witch-body-content">
            <div class="witch-tabs-container"></div>
            <div class="witch-main-content">
                 <div class="witch-info-item" id="global-task-container" style="display: none; margin-bottom: 15px;"></div>
                <div id="character-details-wrapper"></div>
                <div class="no-char-selected">Awaiting Resonance...</div>
            </div>
        </div>
    </div>
    <script>
    document.addEventListener('DOMContentLoaded', function() {
        const container = document.querySelector('.witch-status-container');
        if (!container) { console.error("Main container not found!"); return; }

        const dataContainer = container.previousElementSibling;
        const toggleBtn = container.querySelector('.witch-header-toggle-btn');
        const ui = {
            tabs: container.querySelector('.witch-tabs-container'),
            wrapper: container.querySelector('#character-details-wrapper'),
            placeholder: container.querySelector('.no-char-selected'),
            globalTask: container.querySelector('#global-task-container')
        };
        const bayonettaAvatar = 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAIxMGhztZ9JNdIp_IGz2goDB6Z17IbFAAJYGAACeIOgVymuDmzOSu2LNgQ.jpg';

        const ICONS = {
            '称号': `<svg viewBox="0 0 24 24"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>`,
            '当前任务': `<svg viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>`,
            '服装': `<svg viewBox="0 0 24 24"><path d="M20 7h-4V4c0-1.1-.9-2-2-2h-4c-1.1 0-2 .9-2 2v3H4c-1.1 0-2 .9-2 2v11c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V9c0-1.1-.9-2-2-2zM10 4h4v3h-4V4z"/></svg>`,
            '状态': `<svg viewBox="0 0 24 24"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>`,
            '内心想法': `<svg viewBox="0 0 24 24"><path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"/></svg>`,
            '小穴': `<svg viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm-1-12h2v4h-2zm0 6h2v2h-2z"/></svg>`,
            '菊穴': `<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3.2"/><path d="M9 2L7.17 4H4c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2h-3.17L15 2H9zm3 15c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5z"/></svg>`,
            '乳头': `<svg viewBox="0 0 24 24"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" opacity="0.3"/><circle cx="12" cy="12" r="4"/></svg>`,
            '玉足': `<svg viewBox="0 0 24 24"><path d="M22 18V6c0-1.1-.9-2-2-2H4c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2zM4 6h16v3H4V6zm11 11.5c0-1.93-1.57-3.5-3.5-3.5S8 15.57 8 17.5h7z"/></svg>`,
            '肉棒': `<svg viewBox="0 0 24 24"><path d="M14.54 16.63L16.42 12l2.31-7.58c.24-.79-.43-1.58-1.22-1.33L9.65 5.5l.89 2.92-2.12 2.12-2.4-1.2-1.42 1.42 1.2 2.4-2.12 2.12-2.92-.89-2.41 7.86c.25.79 1.04 1.46 1.83 1.22l7.58-2.31z"/></svg>`,
            'DEFAULT': `<svg viewBox="0 0 24 24"><path d="M9.5 2c-1.82 0-3.53.5-5 1.35C2.39 5.36 1.13 9.42 1.01 13.5H1v1h22v-1h-1.01c-.12-4.08-1.38-8.14-3.49-10.15C16.03 2.5 14.32 2 12.5 2h-3zm0 2h3c1.13 0 2.44.34 3.51 1.02C17.26 6.07 18.06 8.79 18.17 12H4.83c.11-3.21.91-5.93 2.27-7.98C8.16 4.34 9.17 4 10 4h2v-.5z"/></svg>`
        };
        const RESERVED_KEYS = ['姓名', '称号', '内心想法', '好感度', '当前任务'];

        function parseData(text) {
            const data = { characters: [] };
            const sections = text.trim().split('[人物]');
            let globalInfoBlock = sections.shift().trim();
            const globalLines = globalInfoBlock.split('\\n');
            globalLines.forEach(line => {
                const parts = line.split(':'); if (parts.length < 2) return;
                const key = parts[0].trim(); const value = parts.slice(1).join(':').trim();
                if (key === '时间') data.date_string = value;
                if (key === '地点') data.location = value;
                if (key === '当前任务') data.global_task = value;
            });
            sections.forEach(charBlock => {
                if (charBlock.trim() === '') return;
                const charData = {};
                charBlock.trim().split('\\n').forEach(line => {
                    const cleanLine = line.trim();
                    if (cleanLine.startsWith('#') || cleanLine === '') return;
                    const parts = cleanLine.split(':'); if (parts.length < 2) return;
                    charData[parts[0].trim()] = parts.slice(1).join(':').trim();
                });
                data.characters.push(charData);
            });
            return data;
        }

        function createInfoItem(label, value) {
            const iconSvg = ICONS[label] || ICONS['DEFAULT'];
            let item = document.createElement('div');
            item.className = 'witch-info-item';
            if (label === '内心想法') item.classList.add('border-thoughts');
            if (label === '当前任务') item.style.borderColor = '#f59e0b'; // Gold border for tasks
            item.innerHTML = `
                <div class="witch-info-icon">${iconSvg}</div>
                <div class="witch-info-content">
                    <span class="witch-info-label">${label}</span>
                    <span class="witch-info-value">${value}</span>
                </div>`;
            return item;
        }

        function createDetailView(char) {
            const view = document.createElement('div');
            view.className = 'character-detail-view';
            const avatarHtml = (char.姓名 === '{{user}}') ? `<div class="user_avatar"></div>` : `<img src="${bayonettaAvatar}" alt="${char.姓名}" class="witch-avatar">`;

            let statsBarHtml = '';
            if (char.好感度) {
                statsBarHtml = `
                    <div class="witch-stat-bar-container">
                        <div class="witch-stat-bar-label"><span>好感度</span><span>${char.好感度}/100</span></div>
                        <div class="witch-progress-bar-bg"><div class="witch-progress-bar bar-affinity" style="width: ${char.好感度}%;"></div></div>
                    </div>`;
            }

            view.innerHTML = `
                <div class="witch-top-section">
                    <div class="witch-avatar-section">
                        <div class="witch-avatar-frame">${avatarHtml}</div>
                        <div class="witch-char-name">${char.姓名 || 'Unknown'}</div>
                        <div class="witch-char-title">${char.称号 || ''}</div>
                    </div>
                    <div class="witch-stat-bars">${statsBarHtml}</div>
                </div>`;

            const grid = document.createElement('div');
            grid.className = 'witch-info-grid';

            Object.keys(char).forEach(key => {
                if (!RESERVED_KEYS.includes(key)) {
                    grid.appendChild(createInfoItem(key, char[key]));
                }
            });
            if (char.内心想法) grid.appendChild(createInfoItem('内心想法', char.内心想法));

            view.appendChild(grid);
            return view;
        }

        function renderUI(data) {
            if (container.querySelector('.witch-header-title')) {
                container.querySelector('.witch-header-title').innerHTML = `STATUS - ${data.date_string || 'UNKNOWN'}`;
            }

            if(data.global_task) {
                ui.globalTask.innerHTML = createInfoItem('当前任务', data.global_task).innerHTML;
                ui.globalTask.style.borderColor = '#f59e0b';
                ui.globalTask.style.display = 'flex';
            } else {
                ui.globalTask.style.display = 'none';
            }


            data.characters.sort((a, b) => {
                if (a.姓名 === '贝优妮塔') return -1;
                if (b.姓名 === '贝优妮塔') return 1;
                return 0;
            });

            ui.tabs.innerHTML = '';
            ui.wrapper.innerHTML = '';
            if (!data.characters || data.characters.length === 0) {
                 ui.placeholder.style.display = 'block';
                 ui.wrapper.style.display = 'none';
                 return;
            }
            ui.placeholder.style.display = 'none';
            ui.wrapper.style.display = 'block';

            data.characters.forEach((char, index) => {
                const tab = document.createElement('div');
                tab.className = 'witch-char-tab';
                tab.textContent = char.姓名;
                tab.dataset.charIndex = index;
                ui.tabs.appendChild(tab);
                const detailView = createDetailView(char);
                ui.wrapper.appendChild(detailView);
                tab.addEventListener('click', () => {
                    document.querySelectorAll('.witch-char-tab').forEach(t => t.classList.remove('active'));
                    tab.classList.add('active');
                    document.querySelectorAll('.character-detail-view').forEach(v => v.classList.remove('active'));
                    detailView.classList.add('active');
                });
            });

            if (ui.tabs.firstChild) {
                ui.tabs.firstChild.click();
            }
        }

        toggleBtn.addEventListener('click', () => {
            container.classList.toggle('collapsed');
            const isCollapsed = container.classList.contains('collapsed');
            toggleBtn.innerHTML = isCollapsed ? '&#9660;' : '&#9650;';
        });

        const rawData = dataContainer.textContent.trim().replace(/\[魔女启\]|\[魔女关\]/g, '').replace(/\n/g, '\\n');
        if (rawData) {
            const parsedData = parseData(rawData);
            renderUI(parsedData);
        } else {
            console.error("No data in container.");
            ui.placeholder.style.display = 'block';
            ui.wrapper.style.display = 'none';
        }
    });
    </script>
</body>
</html>
